// Reef tank pH logger.
// Linearized probe on A0, optional low-pH LED on D13, UART log at 9600.

const int PROBE_PIN = A0;
const int ALERT_PIN = 13;
const float ALERT_PH = 7.20f;
const unsigned long LOG_PERIOD_MS = 1000;

unsigned long lastLogMs = 0;
unsigned long sampleCount = 0;
float lastPh = 0.0f;
float phMin = 14.0f;
float phMax = 0.0f;
bool alertOn = false;

float adcToMillivolts(int raw)
{
    return raw * (5000.0f / 1023.0f);
}

float computePh(float millivolts)
{
    return millivolts / 500.0f;
}

void trackRange(float ph)
{
    if (ph < phMin)
    {
        phMin = ph;
    }
    if (ph > phMax)
    {
        phMax = ph;
    }
}

void setAlert(bool on)
{
    alertOn = on;
    digitalWrite(ALERT_PIN, on ? HIGH : LOW);
}

void writeLogLine()
{
    Serial.print("pH: ");
    Serial.println(lastPh, 2);
}

void setup()
{
    pinMode(ALERT_PIN, OUTPUT);
    digitalWrite(ALERT_PIN, LOW);
    Serial.begin(9600);
    lastLogMs = millis();
}

void loop()
{
    int raw = analogRead(PROBE_PIN);
    float mv = adcToMillivolts(raw);
    lastPh = computePh(mv);
    sampleCount++;
    trackRange(lastPh);

    if (lastPh < ALERT_PH)
    {
        setAlert(true);
    }
    else
    {
        setAlert(false);
    }

    unsigned long now = millis();
    if (now - lastLogMs >= LOG_PERIOD_MS)
    {
        lastLogMs = now;
        writeLogLine();
    }
}

// Attic ridge-vent controller for an Uno.
// LM35 on A0, relay driver on D8, momentary override on D3 (pull-up).

const int TEMP_PIN = A0;
const int FAN_PIN = 8;
const int OVERRIDE_PIN = 3;

const float FAN_ON_C = 42.0f;
const float FAN_OFF_C = 38.0f;
const float MV_PER_C = 10.0f;
const unsigned long SAMPLE_MS = 50;
const unsigned long STATUS_MS = 1000;
const unsigned long RATE_WINDOW_MS = 5000;
const int MAX_TRANSITIONS = 2;

bool fanRunning = false;
unsigned long lastSampleMs = 0;
unsigned long lastStatusMs = 0;
float lastTempC = 0.0f;

// Transition history for rate limiting.
unsigned long transitionTimes[MAX_TRANSITIONS];
int transitionCount = 0;

float readAtticTempC()
{
    int raw = analogRead(TEMP_PIN);
    float millivolts = raw * (5000.0f / 1024.0f);
    return millivolts / MV_PER_C;
}

bool rateLimitAllows(unsigned long now)
{
    // Drop entries older than the window.
    int kept = 0;
    for (int i = 0; i < transitionCount; i++)
    {
        if (now - transitionTimes[i] < RATE_WINDOW_MS)
        {
            transitionTimes[kept++] = transitionTimes[i];
        }
    }
    transitionCount = kept;
    return transitionCount < MAX_TRANSITIONS;
}

void applyFan(bool wantOn, unsigned long now)
{
    if (wantOn == fanRunning)
    {
        return;
    }
    if (!rateLimitAllows(now))
    {
        return;
    }
    fanRunning = wantOn;
    digitalWrite(FAN_PIN, wantOn ? HIGH : LOW);
    if (transitionCount < MAX_TRANSITIONS)
    {
        transitionTimes[transitionCount++] = now;
    }
}

void publishStatus()
{
    Serial.print("attic: ");
    Serial.print(lastTempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanRunning ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    pinMode(OVERRIDE_PIN, INPUT_PULLUP);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastSampleMs = millis();
    lastStatusMs = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSampleMs >= SAMPLE_MS)
    {
        lastSampleMs = now;
        lastTempC = readAtticTempC();

        bool overrideHeld = (digitalRead(OVERRIDE_PIN) == LOW);
        bool wantOn = fanRunning;

        if (overrideHeld)
        {
            wantOn = true;
        }
        else if (lastTempC >= FAN_ON_C)
        {
            wantOn = true;
        }
        else if (lastTempC <= FAN_OFF_C)
        {
            wantOn = false;
        }
        // else: within hysteresis band, hold current state.

        applyFan(wantOn, now);
    }

    if (now - lastStatusMs >= STATUS_MS)
    {
        lastStatusMs = now;
        publishStatus();
    }
}

// Electronics-bench user LED mirror.
// Momentary probe button on D2 (pull-up), user LED on D13.
// Mode switch on D4 (pull-up) selects steady vs blink-while-held.

const int BTN_PIN = 2;
const int LED_PIN = 13;
const int MODE_PIN = 4;
const unsigned long BLINK_MS = 120;
const unsigned long STATUS_MS = 1000;

bool lit = false;
unsigned long lastBlink = 0;
unsigned long lastStatus = 0;
unsigned long pressStart = 0;
bool wasPressed = false;

void setLed(bool on)
{
    lit = on;
    digitalWrite(LED_PIN, on ? HIGH : LOW);
}

void publishStatus()
{
    unsigned long held = wasPressed ? (millis() - pressStart) : 0;
    Serial.print("bench led=");
    Serial.print(lit ? 1 : 0);
    Serial.print(" held_ms=");
    Serial.println(held);
}

void setup()
{
    pinMode(BTN_PIN, INPUT_PULLUP);
    pinMode(MODE_PIN, INPUT_PULLUP);
    pinMode(LED_PIN, OUTPUT);
    setLed(false);
    Serial.begin(9600);
    lastBlink = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();
    bool pressed = (digitalRead(BTN_PIN) == LOW);
    bool blinkMode = (digitalRead(MODE_PIN) == LOW);

    if (pressed && !wasPressed)
    {
        pressStart = now;
        lastBlink = now;
        setLed(true);
    }
    wasPressed = pressed;

    if (!pressed)
    {
        setLed(false);
    }
    else if (!blinkMode)
    {
        setLed(true);
    }
    else
    {
        if (now - lastBlink >= BLINK_MS)
        {
            lastBlink += BLINK_MS;
            setLed(!lit);
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus += STATUS_MS;
        publishStatus();
    }
}

// Blend-tank concentration logger for a process skid.
// Probe on A4 (10 mV/%). Sample button on D5 (pull-up) forces an early print.

const int CONC_PIN = A4;
const int SAMPLE_BTN = 5;
const int WINDOW = 50;
const float MV_PER_PCT = 10.0f;
const unsigned long IDLE_MS = 20;
const unsigned long STATUS_MS = 1000;

long sum = 0;
int n = 0;
float lastPct = 0.0f;
unsigned long lastStatus = 0;
unsigned long batches = 0;
bool lastBtn = HIGH;

float rawToPct(int raw)
{
    // Default reference is Vcc (~5.0 V). Use 5000 mV full scale.
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_PCT;
}

void resetWindow()
{
    sum = 0;
    n = 0;
}

void publishPct(float pct)
{
    Serial.print("pct: ");
    Serial.println(pct, 1);
    lastPct = pct;
    batches++;
}

void forceSampleNote()
{
    Serial.print("blend force last=");
    Serial.println(lastPct, 1);
}

void setup()
{
    pinMode(SAMPLE_BTN, INPUT_PULLUP);
    Serial.begin(9600);
    resetWindow();
    lastStatus = millis();
}

void loop()
{
    int raw = analogRead(CONC_PIN);
    sum += raw;
    n++;

    // Edge-detect the force button so a press emits one note.
    bool btn = digitalRead(SAMPLE_BTN);
    if (btn == LOW && lastBtn == HIGH)
    {
        forceSampleNote();
    }
    lastBtn = btn;

    unsigned long now = millis();
    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        int avg = (n > 0) ? (int)(sum / n) : 0;
        float pct = rawToPct(avg);
        publishPct(pct);
        resetWindow();
        Serial.print("blend batches=");
        Serial.println(batches);
    }

    delay(IDLE_MS);
}

// Boiler gas-valve thermostat
// Probe on A1 (10 mV/°C), gas valve on D6, lockout key on D3 (active LOW).

const int TEMP_PIN = A1;
const int VALVE_PIN = 6;
const int LOCK_PIN = 3;

const float FIRE_ON_C   = 70.0f;
const float FIRE_OFF_C  = 75.0f;
const float FAULT_LOW_C = 5.0f;
const float FAULT_HIGH_C= 120.0f;
const float MV_PER_C    = 10.0f;

const unsigned long TICK_MS   = 40;
const unsigned long STATUS_MS = 1000;
const unsigned long DEBOUNCE_MS = 50;

bool firing = false;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
float tempC = 0.0f;

// lockout debounce state
bool lockRaw = false;
bool lockStable = false;
unsigned long lockChangeMs = 0;

float readBoilerC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void setValve(bool openValve)
{
    firing = openValve;
    digitalWrite(VALVE_PIN, openValve ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("boiler: ");
    Serial.print(tempC, 1);
    Serial.print(" C valve=");
    Serial.println(firing ? "OPEN" : "SHUT");
}

void setup()
{
    pinMode(VALVE_PIN, OUTPUT);
    pinMode(LOCK_PIN, INPUT_PULLUP);
    setValve(false);
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
    lockRaw = (digitalRead(LOCK_PIN) == LOW);
    lockStable = lockRaw;
    lockChangeMs = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        tempC = readBoilerC();

        // Debounce lockout key (active LOW)
        bool raw = (digitalRead(LOCK_PIN) == LOW);
        if (raw != lockRaw)
        {
            lockRaw = raw;
            lockChangeMs = now;
        }
        if ((now - lockChangeMs) >= DEBOUNCE_MS && lockStable != lockRaw)
        {
            lockStable = lockRaw;
        }

        bool fault = (tempC < FAULT_LOW_C) || (tempC > FAULT_HIGH_C);

        if (lockStable || fault)
        {
            setValve(false);
        }
        else if (tempC < FIRE_ON_C)
        {
            setValve(true);
        }
        else if (tempC > FIRE_OFF_C)
        {
            setValve(false);
        }
        // else: within 70..75 band, hold current state (hysteresis)
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Small boiler gas-valve thermostat.
// Probe on A1 (10 mV/°C), gas valve on D6, lockout key on D3.

const int TEMP_PIN = A1;
const int VALVE_PIN = 6;
const int LOCK_PIN = 3;
const float FIRE_ON_C = 70.0f;
const float FIRE_OFF_C = 75.0f;
const float OVER_TEMP_C = 120.0f;
const float UNDER_TEMP_C = 5.0f;
const float MV_PER_C = 10.0f;
const unsigned long TICK_MS = 40;
const unsigned long STATUS_MS = 1000;

bool firing = false;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
float tempC = 0.0f;

float readBoilerC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void setValve(bool openValve)
{
    firing = openValve;
    digitalWrite(VALVE_PIN, openValve ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("boiler: ");
