            applyHeater(false);
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        publishStatus();
    }
}

// Basement sump controller.
// Linear level sensor on A1 (10 mV/cm), pump contactor on D7,
// silence button on D4 (active LOW, pull-up).

const uint8_t LEVEL_PIN = A1;
const uint8_t PUMP_PIN = 7;
const uint8_t SILENCE_PIN = 4;

const float START_CM = 45.0f;
const float STOP_CM = 30.0f;
const float MV_PER_CM = 10.0f;
const unsigned long POLL_MS = 40;
const unsigned long LOG_MS = 800;
const unsigned long DEBOUNCE_MS = 30;
const unsigned long TOGGLE_WINDOW_MS = 5000;
const uint8_t MAX_TOGGLES = 2;

bool pumpOn = false;
bool silenceLatched = false;
unsigned long lastPoll = 0;
unsigned long lastLog = 0;
float levelCm = 0.0f;

// Debounce state for silence button
bool silenceRaw = false;
bool silenceStable = false;
unsigned long silenceChangeMs = 0;

// Toggle-rate limiter
unsigned long toggleTimes[MAX_TOGGLES];
uint8_t toggleCount = 0;
uint8_t toggleIdx = 0;

float sampleLevelCm()
{
    int adc = analogRead(LEVEL_PIN);
    float mv = adc * (5000.0f / 1024.0f);
    return mv / MV_PER_CM;
}

bool toggleAllowed(unsigned long now)
{
    if (toggleCount < MAX_TOGGLES) return true;
    // Oldest entry is at toggleIdx (next to be overwritten)
    unsigned long oldest = toggleTimes[toggleIdx];
    return (now - oldest) >= TOGGLE_WINDOW_MS;
}

void recordToggle(unsigned long now)
{
    toggleTimes[toggleIdx] = now;
    toggleIdx = (toggleIdx + 1) % MAX_TOGGLES;
    if (toggleCount < MAX_TOGGLES) toggleCount++;
}

void setPump(bool on, unsigned long now)
{
    if (on == pumpOn) return;
    if (!toggleAllowed(now)) return;
    pumpOn = on;
    digitalWrite(PUMP_PIN, on ? HIGH : LOW);
    recordToggle(now);
}

void emitLog()
{
    Serial.print("sump cm=");
    Serial.print(levelCm, 1);
    Serial.print(" pump=");
    Serial.print(pumpOn ? 1 : 0);
    Serial.print(" mute=");
    Serial.println(silenceLatched ? 1 : 0);
}

void setup()
{
    pinMode(PUMP_PIN, OUTPUT);
    pinMode(SILENCE_PIN, INPUT_PULLUP);
    digitalWrite(PUMP_PIN, LOW);
    Serial.begin(9600);
    lastPoll = millis();
    lastLog = millis();
    silenceRaw = (digitalRead(SILENCE_PIN) == LOW);
    silenceStable = silenceRaw;
    silenceChangeMs = millis();
}

void loop()
{
    unsigned long t = millis();

    // Debounce silence button
    bool raw = (digitalRead(SILENCE_PIN) == LOW);
    if (raw != silenceRaw)
    {
        silenceRaw = raw;
        silenceChangeMs = t;
    }
    if ((t - silenceChangeMs) >= DEBOUNCE_MS && silenceStable != silenceRaw)
    {
        silenceStable = silenceRaw;
        if (silenceStable)
        {
            silenceLatched = true;
            setPump(false, t);
        }
    }

    if (t - lastPoll >= POLL_MS)
    {
        lastPoll = t;
        levelCm = sampleLevelCm();

        if (!silenceLatched)
        {
            if (!pumpOn && levelCm >= START_CM)
            {
                setPump(true, t);
            }
            else if (pumpOn && levelCm <= STOP_CM)
            {
                setPump(false, t);
            }
        }
    }

    if (t - lastLog >= LOG_MS)
    {
        lastLog = t;
        emitLog();
    }
}

// Walk-in cooler compressor controller (patched).
// Cabinet probe on A3 (10 mV/°C), compressor on D7, service switch on D4.

const int TEMP_PIN = A3;
const int COMP_PIN = 7;
const int SERVICE_PIN = 4;
const float COOL_ON_C = 8.0f;
const float COOL_OFF_C = 4.0f;
const float FAULT_LOW_C = 0.0f;
const float FAULT_HIGH_C = 60.0f;
const float MV_PER_C = 10.0f;
const unsigned long TICK_MS = 50;
const unsigned long STATUS_MS = 1000;
const int HOLD_N = 3;
// Floating-detect: a real probe sits well below mid-rail; a floating pin
// typically reads near mid-supply. Treat near-rail as invalid.
const float FLOAT_MV_LOW = 50.0f;    // below this = likely shorted/floating low
const float FLOAT_MV_HIGH = 4500.0f; // above this = likely floating high

bool cooling = false;
int onHold = 0;
int offHold = 0;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
float tempC = 0.0f;
bool sensorValid = false;

float readTempC(float &mvOut)
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    mvOut = mv;
    return mv / MV_PER_C;
}

void setCompressor(bool on)
{
    cooling = on;
    digitalWrite(COMP_PIN, on ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("cooler: ");
    Serial.print(tempC, 1);
    Serial.print(" C comp=");
    Serial.println(cooling ? "ON" : "OFF");
}

void setup()
{
    pinMode(COMP_PIN, OUTPUT);
    pinMode(SERVICE_PIN, INPUT_PULLUP);
    setCompressor(false);
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        float mv;
        tempC = readTempC(mv);
        sensorValid = (mv > FLOAT_MV_LOW) && (mv < FLOAT_MV_HIGH);
        bool service = (digitalRead(SERVICE_PIN) == LOW);
        bool fault = (!sensorValid) || (tempC < FAULT_LOW_C) || (tempC > FAULT_HIGH_C);

        if (service || fault)
        {
            onHold = 0;
            offHold = 0;
            setCompressor(false);
        }
        else
        {
            // Hysteresis state machine: only act on the threshold that
            // matches the current state, with a short debounce hold.
            if (!cooling)
            {
                if (tempC >= COOL_ON_C) onHold++;
                else onHold = 0;
                offHold = 0;
                if (onHold >= HOLD_N) { setCompressor(true); onHold = 0; }
            }
            else
            {
                if (tempC <= COOL_OFF_C) offHold++;
                else offHold = 0;
                onHold = 0;
                if (offHold >= HOLD_N) { setCompressor(false); offHold = 0; }
            }
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Greenhouse nutrient drip pulse scheduler.
// Pulse driver on D8, pause button on D4 (pull-up).

const int DRIP_PIN = 8;
const int PAUSE_PIN = 4;
const unsigned long PERIOD_MS = 800;
const unsigned long PULSE_MS = 50;
const unsigned long LOG_MS = 1600;

unsigned long nextDue = 0;
unsigned long pulseUntil = 0;
unsigned long lastLog = 0;
unsigned long dripCount = 0;
bool pulsing = false;
bool paused = false;

void dripHigh()
{
    digitalWrite(DRIP_PIN, HIGH);
}

void dripLow()
{
    digitalWrite(DRIP_PIN, LOW);
}

void startPulse(unsigned long now)
{
    pulsing = true;
    pulseUntil = now + PULSE_MS;
    dripHigh();
    dripCount++;
    Serial.println("drip");
}

void endPulse()
{
    pulsing = false;
    dripLow();
}

void printLog()
{
    Serial.print("drip n=");
    Serial.print(dripCount);
    Serial.print(" pause=");
    Serial.println(paused ? 1 : 0);
}

void setup()
{
    pinMode(DRIP_PIN, OUTPUT);
    pinMode(PAUSE_PIN, INPUT_PULLUP);
    dripLow();
    Serial.begin(9600);
    unsigned long now = millis();
    nextDue = now + PERIOD_MS;
    lastLog = now;
}

void loop()
{
    unsigned long now = millis();
    paused = (digitalRead(PAUSE_PIN) == LOW);

    if (paused)
    {
        if (pulsing)
        {
            endPulse();
        }
        nextDue = now + PERIOD_MS;
    }
    else
    {
        if (pulsing && (long)(now - pulseUntil) >= 0)
        {
            endPulse();
        }

        if (!pulsing && (long)(now - nextDue) >= 0)
        {
            nextDue += PERIOD_MS;
            if ((long)(now - nextDue) >= 0)
            {
                nextDue = now + PERIOD_MS;
            }
            startPulse(now);
        }
    }

    if (now - lastLog >= LOG_MS)
    {
        lastLog += LOG_MS;
        if ((long)(now - lastLog) >= LOG_MS)
        {
            lastLog = now;
        }
        printLog();
    }
}

// Foyer wall switch: one pushbutton toggles a lamp channel.
// Button D5 to ground (pull-up), lamp driver D11, status over serial.

const int SWITCH_PIN = 5;
const int LAMP_PIN = 11;
const unsigned long STATUS_EVERY_MS = 1500;
const unsigned long DEBOUNCE_MS = 40;

bool lampLit = false;
int stableState = HIGH;      // debounced logical state
int lastRaw = HIGH;          // last raw reading
unsigned long lastChangeMs = 0;
unsigned long lastStatusAt = 0;
unsigned long pressEvents = 0;

void driveLamp(bool on)
{
    lampLit = on;
    digitalWrite(LAMP_PIN, on ? HIGH : LOW);
}

void flipLamp()
{
    driveLamp(!lampLit);
    pressEvents++;
}

void reportLamp()
{
    Serial.print("foyer lamp=");
    Serial.println(lampLit ? "ON" : "OFF");
}

void setup()
{
    pinMode(SWITCH_PIN, INPUT_PULLUP);
    pinMode(LAMP_PIN, OUTPUT);
    driveLamp(false);
    Serial.begin(9600);
    lastRaw = digitalRead(SWITCH_PIN);
    stableState = lastRaw;
    lastChangeMs = millis();
    lastStatusAt = millis();
}

void loop()
{
    int raw = digitalRead(SWITCH_PIN);
    unsigned long now = millis();

    if (raw != lastRaw)
    {
        lastRaw = raw;
        lastChangeMs = now;
    }

    if ((now - lastChangeMs) >= DEBOUNCE_MS && raw != stableState)
    {
        int prev = stableState;
        stableState = raw;
        // Accept only settled HIGH->LOW (press) edges.
        if (prev == HIGH && stableState == LOW)
        {
            flipLamp();
        }
    }

    if (now - lastStatusAt >= STATUS_EVERY_MS)
    {
        lastStatusAt = now;
        reportLamp();
    }
}

// Packaging glue-dot solenoid driver.
// Trigger on D2 (pull-up), solenoid on D8, armed LED on D11.

const int TRIG_PIN = 2;
const int SOL_PIN = 8;
const int ARMED_PIN = 11;
const unsigned long PULSE_MS = 2500;
const unsigned long DEBOUNCE_MS = 25;
const unsigned long HB_MS = 500;

bool pulsing = false;
unsigned long pulseStart = 0;
int stableTrig = HIGH;
int lastRaw = HIGH;
unsigned long rawChange = 0;
unsigned long lastHb = 0;
unsigned long dots = 0;

void solHigh()
{
    digitalWrite(SOL_PIN, HIGH);
}

void solLow()
{
    digitalWrite(SOL_PIN, LOW);
}

void setArmedLed(bool on)
{
    digitalWrite(ARMED_PIN, on ? HIGH : LOW);
}

void heartbeat()
{
    Serial.print("glue dots=");
    Serial.print(dots);
    Serial.print(" busy=");
    Serial.println(pulsing ? 1 : 0);
}

void setup()
{
    pinMode(TRIG_PIN, INPUT_PULLUP);
    pinMode(SOL_PIN, OUTPUT);
    pinMode(ARMED_PIN, OUTPUT);
    solLow();
    setArmedLed(true);
    Serial.begin(9600);
    stableTrig = digitalRead(TRIG_PIN);
    lastRaw = stableTrig;
    rawChange = millis();
    lastHb = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(TRIG_PIN);

    if (raw != lastRaw)
    {
        lastRaw = raw;
        rawChange = now;
    }

    if ((now - rawChange) >= DEBOUNCE_MS && raw != stableTrig)
    {
        stableTrig = raw;
        if (stableTrig == LOW && !pulsing)
        {
            pulsing = true;
            pulseStart = now;
            dots++;
            solHigh();
            setArmedLed(false);
        }
    }

    if (pulsing && (now - pulseStart) >= PULSE_MS)
    {
        pulsing = false;
        solLow();
        setArmedLed(true);
    }

    if (now - lastHb >= HB_MS)
    {
        lastHb = now;
        heartbeat();
    }
}

// Greenhouse ridge-vent controller.
// LM35 air probe on A2, exhaust fan relay on D9, UART status.

const int SENSOR_PIN = A2;
const int FAN_PIN = 9;
const float OPEN_C = 28.0f;
const float CLOSE_C = 24.0f;
const float MIN_VALID_C = 5.0f;
const float MAX_VALID_C = 100.0f;
const float MV_PER_C = 10.0f;
const unsigned long TICK_MS = 50;
const unsigned long STATUS_MS = 1000;
const unsigned long MAX_CHANGES = 2;
const unsigned long WINDOW_MS = 5000;
const unsigned long FAILSAFE_MS = 600;

bool fanOn = false;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
unsigned long changeTimes[MAX_CHANGES];
unsigned long changeCount = 0;
unsigned long faultStart = 0;
bool faultActive = false;
float tempC = 0.0f;

float readTempC()
{
    int raw = analogRead(SENSOR_PIN);
    float mv = raw * (5000.0f / 1024.0f);
    return mv / MV_PER_C;
}

bool probeFault(float c)
{
    // Floating probe: near 0 V or near 5 V (LM35 would read <0 or >500 C)
    if (c < MIN_VALID_C || c > MAX_VALID_C)
    {
        return true;
    }
    return false;
}

bool canChangeFan(unsigned long now)
{
    // Remove changes older than window
    unsigned long kept = 0;
    for (unsigned long i = 0; i < changeCount; i++)
    {
        if (now - changeTimes[i] < WINDOW_MS)
        {
            changeTimes[kept++] = changeTimes[i];
        }
    }
    changeCount = kept;
    return changeCount < MAX_CHANGES;
}

void setFan(bool on, unsigned long now)
{
    if (on == fanOn)
    {
        return;
    }
    if (!canChangeFan(now))
    {
        return;
    }
    fanOn = on;
    digitalWrite(FAN_PIN, on ? HIGH : LOW);
    if (changeCount < MAX_CHANGES)
    {
        changeTimes[changeCount++] = now;
    }
}

void printStatus()
{
    Serial.print("gh: ");
    Serial.print(tempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        tempC = readTempC();

        if (probeFault(tempC))
        {
            if (!faultActive)
            {
                faultActive = true;
                faultStart = now;
            }
            // Force fan ON within FAILSAFE_MS and hold
            if (now - faultStart >= FAILSAFE_MS)
            {
                setFan(true, now);
            }
        }
        else
        {
            faultActive = false;
            if (tempC >= OPEN_C)
            {
                setFan(true, now);
            }
            else if (tempC <= CLOSE_C)
            {
                setFan(false, now);
            }
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Potting-shed vent controller (patched).
// Air probe on A0, vent fan on D6, UART status.

const int TEMP_PIN = A0;
const int FAN_PIN = 6;
const float OPEN_C = 30.0f;
const float CLOSE_C = 26.0f;
const float FAULT_LOW_C = 5.0f;
const float FAULT_HIGH_C = 100.0f;
const float MV_PER_C = 10.0f;
const unsigned long TICK_MS = 50;
const unsigned long STATUS_MS = 1000;
const unsigned long TOGGLE_WINDOW_MS = 5000;
const int MAX_TOGGLES = 2;
const int HOLD_N = 4;      // 200 ms debounce for band crossings
const int FAULT_N = 4;     // 200 ms to latch fault (well under 600 ms)
const int CLEAR_N = 8;     // 400 ms to clear fault

bool fanOn = false;
bool faultLatched = false;
int openHold = 0;
int closeHold = 0;
int faultHold = 0;
int clearHold = 0;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
float tempC = 0.0f;
bool haveTemp = false;

// Toggle-rate limiter: timestamps of recent fan state changes
unsigned long toggleTimes[MAX_TOGGLES];
int toggleCount = 0;

float readTempC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

bool probeFloating(int raw)
{
    // A truly floating input tends to rail or sit at an unstable value.
    // Treat near-rail readings as invalid (open circuit).
    return (raw <= 2) || (raw >= 1021);
}

void setFan(bool on)
{
    if (on == fanOn) return;
    fanOn = on;
    digitalWrite(FAN_PIN, on ? HIGH : LOW);
    // record toggle time
    if (toggleCount < MAX_TOGGLES)
    {
        toggleTimes[toggleCount++] = millis();
    }
    else
    {
        for (int i = 1; i < MAX_TOGGLES; i++) toggleTimes[i-1] = toggleTimes[i];
        toggleTimes[MAX_TOGGLES-1] = millis();
    }
}

bool toggleAllowed(unsigned long now)
{
    // Count toggles within the last TOGGLE_WINDOW_MS
    int recent = 0;
    for (int i = 0; i < toggleCount; i++)
    {
        if (now - toggleTimes[i] < TOGGLE_WINDOW_MS) recent++;
    }
    return recent < MAX_TOGGLES;
}

void printStatus()
{
    Serial.print("shed: ");
    Serial.print(tempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        int raw = analogRead(TEMP_PIN);
        tempC = (raw * (5000.0f / 1023.0f)) / MV_PER_C;
        haveTemp = true;

        bool floating = probeFloating(raw);
        bool outOfRange = floating || (tempC < FAULT_LOW_C) || (tempC > FAULT_HIGH_C);

        if (outOfRange)
        {
            faultHold++;
            clearHold = 0;
            openHold = 0;
            closeHold = 0;
        }
        else
        {
            faultHold = 0;
            clearHold++;
            if (tempC >= OPEN_C) openHold++; else openHold = 0;
            if (tempC <= CLOSE_C) closeHold++; else closeHold = 0;
        }

        if (faultHold >= FAULT_N) faultLatched = true;
        if (faultLatched && clearHold >= CLEAR_N) faultLatched = false;

        bool wantOn = fanOn;
        if (faultLatched) wantOn = true;
        else if (openHold >= HOLD_N) wantOn = true;
        else if (closeHold >= HOLD_N) wantOn = false;

        if (wantOn != fanOn)
        {
            // Fault force-ON bypasses rate limiter; normal toggles are limited.
            if (faultLatched || toggleAllowed(now))
            {
                setFan(wantOn);
            }
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        if (haveTemp) printStatus();
    }
}

// Shop hoist contactor with mushroom e-stop.
// E-stop on D3 (NC to ground via switch, pull-up), contactor on D5.
// Run request on D6 (pull-up).

const int ESTOP_PIN = 3;
const int CONTACTOR_PIN = 5;
const int RUN_PIN = 6;
const unsigned long SETTLE_MS = 30;
const unsigned long BEAT_MS = 1100;

int stableStop = HIGH;
int lastStop = HIGH;
unsigned long stopEdge = 0;
bool contactorOn = false;
unsigned long lastBeat = 0;
unsigned long tripCount = 0;

bool estopActive(int level)
{
    return level == LOW;
}

void setContactor(bool on)
{
    contactorOn = on;
    digitalWrite(CONTACTOR_PIN, on ? HIGH : LOW);
}

void heartbeat()
{
    Serial.print("hoist run=");
    Serial.print(contactorOn ? 1 : 0);
    Serial.print(" trips=");
    Serial.println(tripCount);
}

void setup()
{
    pinMode(ESTOP_PIN, INPUT_PULLUP);
    pinMode(RUN_PIN, INPUT_PULLUP);
    pinMode(CONTACTOR_PIN, OUTPUT);
    setContactor(false);
    Serial.begin(9600);
    stableStop = digitalRead(ESTOP_PIN);
    lastStop = stableStop;
    lastBeat = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(ESTOP_PIN);

    if (raw != lastStop)
    {
        stopEdge = now;
        lastStop = raw;
    }

    if ((now - stopEdge) >= SETTLE_MS && raw != stableStop)
    {
        if (estopActive(raw) && !estopActive(stableStop))
        {
            tripCount++;
        }
        stableStop = raw;
    }

    bool stopped = estopActive(stableStop);
    bool runReq = (digitalRead(RUN_PIN) == LOW);

    if (stopped)
    {
        setContactor(false);
    }
    else if (runReq)
    {
        setContactor(true);
    }
    else
    {
        setContactor(false);
    }

    if (now - lastBeat >= BEAT_MS)
    {
        lastBeat = now;
        heartbeat();
    }
}

// Tool-arm interlock: hold-to-arm then release to clear.
// Hold button on D3 (pull-up), armed lamp on D8.
// Aux confirm on D5 (pull-up) is logged only.

const int HOLD_PIN = 3;
const int ARMED_PIN = 8;
const int CONFIRM_PIN = 5;
const unsigned long ARM_MS = 500;
const unsigned long STATUS_MS = 1000;

bool held = false;
unsigned long downSince = 0;
bool armed = false;
unsigned long lastStatus = 0;
unsigned long armEvents = 0;
bool confirmPrev = false;

void setArmed(bool on)
{
    if (on && !armed)
    {
        armEvents++;
    }
    armed = on;
    digitalWrite(ARMED_PIN, on ? HIGH : LOW);
}

void publishStatus()
{
    Serial.print("arm lit=");
    Serial.print(armed ? 1 : 0);
    Serial.print(" events=");
    Serial.println(armEvents);
}

void setup()
{
    pinMode(HOLD_PIN, INPUT_PULLUP);
    pinMode(CONFIRM_PIN, INPUT_PULLUP);
    pinMode(ARMED_PIN, OUTPUT);
    setArmed(false);
    Serial.begin(9600);
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();
    bool down = (digitalRead(HOLD_PIN) == LOW);
    bool confirm = (digitalRead(CONFIRM_PIN) == LOW);

    if (down)
    {
        if (!held)
        {
            held = true;
            downSince = now;
        }
        if ((now - downSince) >= ARM_MS)
        {
            setArmed(true);
        }
        else
        {
            setArmed(false);
        }
    }
    else
    {
        held = false;
        setArmed(false);
    }

    if (confirm && !confirmPrev)
    {
        Serial.println("arm confirm");
    }
    confirmPrev = confirm;

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        publishStatus();
    }
}

// Bench reagent inject one-shot.
// Start button on D2 (pull-up), inject indicator on D4.
// Heartbeat on UART while idle and during the pulse.

const int START_PIN = 2;
const int INJECT_PIN = 4;
const unsigned long PULSE_MS = 3000;
const unsigned long DEBOUNCE_MS = 30;
const unsigned long HB_MS = 400;

bool pulsing = false;
unsigned long pulseStart = 0;
int stableBtn = HIGH;
int lastBtn = HIGH;
unsigned long btnEdge = 0;
unsigned long lastHb = 0;
unsigned long shots = 0;

void injectHigh()
{
    digitalWrite(INJECT_PIN, HIGH);
}

void injectLow()
{
    digitalWrite(INJECT_PIN, LOW);
}

void sendHb()
{
    Serial.print("inject hb shots=");
    Serial.println(shots);
}

void setup()
{
    pinMode(START_PIN, INPUT_PULLUP);
    pinMode(INJECT_PIN, OUTPUT);
    injectLow();
    Serial.begin(9600);
    stableBtn = digitalRead(START_PIN);
    lastBtn = stableBtn;
    btnEdge = millis();
    lastHb = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(START_PIN);

    if (raw != lastBtn)
    {
        btnEdge = now;
        lastBtn = raw;
    }

    if ((now - btnEdge) >= DEBOUNCE_MS && raw != stableBtn)
    {
        stableBtn = raw;
        if (stableBtn == LOW && !pulsing)
        {
            pulsing = true;
            pulseStart = now;
            shots++;
            injectHigh();
            Serial.println("go");
        }
    }

    if (pulsing && (now - pulseStart) >= PULSE_MS)
    {
        pulsing = false;
        injectLow();
    }

    if (now - lastHb >= HB_MS)
    {
        lastHb = now;
        sendHb();
    }
}

// Studio kiln door interlock siren.
// Door-open switch on D2 (pull-up, active LOW), piezo driver on D8.
// Non-blocking: heartbeat continues during the siren pulse.

const int DOOR_PIN = 2;
const int SIREN_PIN = 8;
const unsigned long SIREN_MS = 2000;
const unsigned long HEARTBEAT_MS = 250;
const unsigned long DEBOUNCE_MS = 40;

unsigned long lastHeartbeat = 0;
unsigned long tripCount = 0;

bool sirenActive = false;
unsigned long sirenStart = 0;

bool lastRaw = false;          // last raw doorOpen reading
bool stableOpen = false;       // debounced state
unsigned long lastChange = 0;  // when raw last changed

void sirenOn()  { digitalWrite(SIREN_PIN, HIGH); }
void sirenOff() { digitalWrite(SIREN_PIN, LOW); }

void emitHeartbeat()
{
    Serial.println("hb");
}

bool doorOpenRaw()
{
    return digitalRead(DOOR_PIN) == LOW;
}

void setup()
{
    pinMode(DOOR_PIN, INPUT_PULLUP);
    pinMode(SIREN_PIN, OUTPUT);
    sirenOff();
    Serial.begin(9600);
    lastHeartbeat = millis();
    lastRaw = doorOpenRaw();
    stableOpen = lastRaw;
    lastChange = millis();
}

void loop()
{
    unsigned long now = millis();

    // Debounce door switch: require stable reading for DEBOUNCE_MS.
    bool raw = doorOpenRaw();
    if (raw != lastRaw)
    {
        lastRaw = raw;
        lastChange = now;
    }
    if ((now - lastChange) >= DEBOUNCE_MS && stableOpen != lastRaw)
    {
        stableOpen = lastRaw;
        // Rising edge of settled door-open starts a pulse if none running.
        if (stableOpen && !sirenActive)
        {
            tripCount++;
            sirenActive = true;
            sirenStart = now;
            sirenOn();
        }
    }

    // End siren pulse after SIREN_MS.
    if (sirenActive && (now - sirenStart) >= SIREN_MS)
    {
        sirenActive = false;
        sirenOff();
    }

    // Heartbeat always runs, even during the siren pulse.
    if ((now - lastHeartbeat) >= HEARTBEAT_MS)
    {
        lastHeartbeat = now;
        emitHeartbeat();
    }
}

// Bench chemistry pH logger for the teaching lab.
// Linearized probe on A1 (500 mV/pH), range LED on D10.

const int PH_PIN = A1;
const int RANGE_PIN = 10;
const float MV_PER_PH = 500.0f;
const float LOW_PH = 6.50f;
const float HIGH_PH = 8.50f;
const unsigned long PERIOD_MS = 1000;

// Probe calibration: pH = (mV - PH_ZERO_MV) / MV_PER_PH
// A 500 mV/pH probe with 0 mV at pH 7.00 (typical lab probe).
const float PH_ZERO_MV = 0.0f;

unsigned long lastPrint = 0;
unsigned long sampleCount = 0;
float phValue = 0.0f;
float phMin = 14.0f;
float phMax = 0.0f;
bool inBand = true;

float adcMillivolts(int raw)
{
    return raw * (5000.0f / 1024.0f);
}

float millivoltsToPh(float mv)
{
    return (mv - PH_ZERO_MV) / MV_PER_PH;
}

void trackPh(float ph)
{
    if (ph < phMin)
    {
        phMin = ph;
    }
    if (ph > phMax)
    {
        phMax = ph;
    }
}

void updateRangeLamp(float ph)
{
    inBand = (ph >= LOW_PH) && (ph <= HIGH_PH);
    digitalWrite(RANGE_PIN, inBand ? LOW : HIGH);
}

void printPh()
{
    Serial.print("pH: ");
    Serial.println(phValue, 2);
}

void setup()
{
    pinMode(RANGE_PIN, OUTPUT);
    digitalWrite(RANGE_PIN, LOW);
    Serial.begin(9600);
    lastPrint = millis();
}

void loop()
{
    int raw = analogRead(PH_PIN);
    float mv = adcMillivolts(raw);
    phValue = millivoltsToPh(mv);
    sampleCount++;
    trackPh(phValue);
    updateRangeLamp(phValue);

    unsigned long now = millis();
    if (now - lastPrint >= PERIOD_MS)
    {
        lastPrint = now;
        printPh();
    }
}

// Compact laundry fill/run cycle controller.
// Level probe on A0 (10 mV/cm), fill valve on D9, drum motor on D10.
// Reset button on D4 (pull-up) returns to IDLE.

const int LEVEL_PIN = A0;
const int VALVE_PIN = 9;
const int MOTOR_PIN = 10;
const int RESET_PIN = 4;
const float EMPTY_CM = 10.0f;
const float FULL_CM = 25.0f;
const float RUN_MIN_CM = 20.0f;
const float MV_PER_CM = 10.0f;
const unsigned long TICK_MS = 40;
const unsigned long STATUS_MS = 1000;

enum CycleState
{
    ST_IDLE = 0,
    ST_FILL = 1,
    ST_RUN = 2
};

CycleState state = ST_IDLE;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
float levelCm = 0.0f;

float readLevelCm()
{
    int raw = analogRead(LEVEL_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_CM;
}

void driveOutputs()
{
    digitalWrite(VALVE_PIN, state == ST_FILL ? HIGH : LOW);
    digitalWrite(MOTOR_PIN, state == ST_RUN ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("laundry st=");
    Serial.print((int)state);
    Serial.print(" cm=");
    Serial.println(levelCm, 1);
}

void setup()
{
    pinMode(VALVE_PIN, OUTPUT);
    pinMode(MOTOR_PIN, OUTPUT);
    pinMode(RESET_PIN, INPUT_PULLUP);
    driveOutputs();
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        levelCm = readLevelCm();

        if (digitalRead(RESET_PIN) == LOW)
        {
            state = ST_IDLE;
        }
        else if (state == ST_IDLE && levelCm < EMPTY_CM)
        {
            state = ST_FILL;
        }
        else if (state == ST_FILL && levelCm >= FULL_CM)
        {
            state = ST_RUN;
        }
        else if (state == ST_RUN && levelCm < RUN_MIN_CM)
        {
            state = ST_IDLE;
        }

        driveOutputs();
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Compact laundry fill/run cycle controller
// Level probe on A0 (10 mV/cm), fill valve on D9, drum motor on D10.
// Reset button on D4 (pull-up) returns to IDLE immediately.

const int LEVEL_PIN = A0;
const int VALVE_PIN = 9;
const int MOTOR_PIN = 10;
const int RESET_PIN = 4;
const float EMPTY_CM = 10.0f;
const float FULL_CM = 25.0f;
const float RUN_MIN_CM = 20.0f;
const float HYST_CM = 0.5f;
const float MV_PER_CM = 10.0f;
const unsigned long TICK_MS = 40;
const unsigned long STATUS_MS = 1000;

enum CycleState
{
    ST_IDLE = 0,
    ST_FILL = 1,
    ST_RUN = 2
};

CycleState state = ST_IDLE;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
float levelCm = 0.0f;

float readLevelCm()
{
    int raw = analogRead(LEVEL_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_CM;
}

void driveOutputs()
{
    digitalWrite(VALVE_PIN, state == ST_FILL ? HIGH : LOW);
    digitalWrite(MOTOR_PIN, state == ST_RUN ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("laundry st=");
    Serial.print((int)state);
    Serial.print(" cm=");
    Serial.println(levelCm, 1);
}

void setup()
{
    pinMode(VALVE_PIN, OUTPUT);
    pinMode(MOTOR_PIN, OUTPUT);
    pinMode(RESET_PIN, INPUT_PULLUP);
    driveOutputs();
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    // Reset is checked every iteration for immediate response.
    if (digitalRead(RESET_PIN) == LOW)
    {
        state = ST_IDLE;
        driveOutputs();
    }

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        levelCm = readLevelCm();

        if (digitalRead(RESET_PIN) == LOW)
        {
            state = ST_IDLE;
        }
        else if (state == ST_IDLE && levelCm < (EMPTY_CM - HYST_CM))
        {
            state = ST_FILL;
        }
        else if (state == ST_FILL && levelCm >= FULL_CM)
        {
            state = ST_RUN;
        }
        else if (state == ST_RUN && levelCm < RUN_MIN_CM)
        {
            state = ST_IDLE;
        }

        driveOutputs();
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Lobby accent lamp toggle with contact settle.
// Momentary switch on D3 (pull-up), lamp channel on D12.

const uint8_t BTN_PIN = 3;
const uint8_t LAMP_PIN = 12;
const unsigned long SETTLE_MS = 45;
const unsigned long STATUS_MS = 1400;

bool lampOn = false;
uint8_t stable = HIGH;
uint8_t lastRaw = HIGH;
unsigned long edgeMs = 0;
unsigned long statusMs = 0;
unsigned long toggles = 0;

void setLamp(bool on)
{
    lampOn = on;
    digitalWrite(LAMP_PIN, on ? HIGH : LOW);
}

void toggleLamp()
{
    setLamp(!lampOn);
    toggles++;
}

void printStatus()
{
    Serial.print("lobby lamp=");
    Serial.print(lampOn ? "ON" : "OFF");
    Serial.print(" n=");
    Serial.println(toggles);
}

void setup()
{
    pinMode(BTN_PIN, INPUT_PULLUP);
    pinMode(LAMP_PIN, OUTPUT);
    setLamp(false);
    Serial.begin(9600);
    stable = digitalRead(BTN_PIN);
    lastRaw = stable;
    edgeMs = millis();
    statusMs = millis();
}

void loop()
{
    uint8_t raw = digitalRead(BTN_PIN);
    unsigned long now = millis();

    // Re-arm the settle timer on any raw transition.
    if (raw != lastRaw)
    {
        edgeMs = now;
        lastRaw = raw;
    }

    // Accept a new stable level only after the input has been
    // unchanged for the full settle window.
    if ((now - edgeMs) >= SETTLE_MS && raw != stable)
    {
        stable = raw;
        if (stable == LOW)
        {
            toggleLamp();
        }
    }

    if (now - statusMs >= STATUS_MS)
    {
        statusMs = now;
        printStatus();
    }
}

// Safe-deposit vault lock latch (patched).
// Request button on D2, door-closed sense on D3 (both pull-up), lock solenoid on D9.

const int REQ_PIN = 2;
const int DOOR_PIN = 3;
const int LOCK_PIN = 9;
const unsigned long DEBOUNCE_MS = 35;
const unsigned long STATUS_MS = 1000;

bool locked = false;
int stableReq = HIGH;
int lastReq = HIGH;
unsigned long reqEdge = 0;
unsigned long lastStatus = 0;
unsigned long engageCount = 0;
bool reqArmed = true;   // must see a fresh press before engaging again

void setLock(bool on)
{
    locked = on;
    digitalWrite(LOCK_PIN, on ? HIGH : LOW);
}

void publishStatus()
{
    Serial.print("vault lock=");
    Serial.print(locked ? 1 : 0);
    Serial.print(" engages=");
    Serial.println(engageCount);
}

bool doorClosed()
{
    return digitalRead(DOOR_PIN) == LOW;
}

void setup()
{
    pinMode(REQ_PIN, INPUT_PULLUP);
    pinMode(DOOR_PIN, INPUT_PULLUP);
    pinMode(LOCK_PIN, OUTPUT);
    setLock(false);
    Serial.begin(9600);
    stableReq = digitalRead(REQ_PIN);
    lastReq = stableReq;
    reqEdge = millis();
    lastStatus = millis();
    reqArmed = (stableReq == HIGH);
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(REQ_PIN);

    if (raw != lastReq)
    {
        reqEdge = now;
        lastReq = raw;
    }

    if ((now - reqEdge) >= DEBOUNCE_MS && raw != stableReq)
    {
        stableReq = raw;
        if (stableReq == HIGH)
        {
            reqArmed = true;   // fresh release arms a new request
        }
        else if (stableReq == LOW && reqArmed && doorClosed() && !locked)
        {
            setLock(true);
            engageCount++;
            reqArmed = false;  // consume this press
        }
    }

    if (!doorClosed())
    {
        setLock(false);
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        publishStatus();
    }
}

// Loft cooling fan with hysteresis, boost button, debounce and toggle-rate limit.
const int TEMP_PIN = A3;
const int FAN_PIN = 5;
const int BOOST_PIN = 4;

const float ON_C = 36.0f;
const float OFF_C = 32.0f;
const float MV_PER_C = 10.0f;
const unsigned long SAMPLE_MS = 50;
const unsigned long LOG_MS = 1000;
const int HOLD = 4;
const unsigned long MIN_TOGGLE_MS = 2500; // 2 changes per 5000 ms
const unsigned long DEBOUNCE_MS = 30;

bool fanOn = false;
int onHold = 0;
int offHold = 0;
unsigned long lastSample = 0;
unsigned long lastLog = 0;
unsigned long lastToggle = 0;
float tempC = 0.0f;

bool boostRaw = false;
bool boostStable = false;
unsigned long boostChangeMs = 0;

float sampleTempC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1024.0f);
    return mv / MV_PER_C;
}

void driveFan(bool on)
{
    if (on == fanOn) return;
    unsigned long now = millis();
    if (now - lastToggle < MIN_TOGGLE_MS) return;
    fanOn = on;
    lastToggle = now;
    digitalWrite(FAN_PIN, on ? HIGH : LOW);
}

void logLine()
{
    Serial.print("loft: ");
    Serial.print(tempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    pinMode(BOOST_PIN, INPUT_PULLUP);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastSample = millis();
    lastLog = millis();
    lastToggle = millis() - MIN_TOGGLE_MS;
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        tempC = sampleTempC();

        bool raw = (digitalRead(BOOST_PIN) == LOW);
        if (raw != boostRaw)
        {
            boostRaw = raw;
            boostChangeMs = now;
        }
        if (now - boostChangeMs >= DEBOUNCE_MS && boostStable != boostRaw)
        {
            boostStable = boostRaw;
        }

        if (boostStable)
        {
            onHold = 0;
            offHold = 0;
            driveFan(true);
        }
        else
        {
            if (tempC >= ON_C) onHold++; else onHold = 0;
            if (tempC <= OFF_C) offHold++; else offHold = 0;

            if (onHold >= HOLD) driveFan(true);
            else if (offHold >= HOLD) driveFan(false);
        }
    }

    if (now - lastLog >= LOG_MS)
    {
        lastLog = now;
        logLine();
    }
}

// Greenhouse mist injector timed pulse.
// Trigger on D4 (pull-up), injector on D9, ready lamp on D12.

const int TRIG_PIN = 4;
const int INJ_PIN = 9;
const int READY_PIN = 12;
const unsigned long PULSE_MS = 800;
const unsigned long DEBOUNCE_MS = 25;
const unsigned long HB_MS = 450;

bool pulsing = false;
unsigned long pulseStart = 0;
int stableTrig = HIGH;
int lastTrig = HIGH;
unsigned long trigEdge = 0;
unsigned long lastHb = 0;
unsigned long shots = 0;

void injHigh()
{
    digitalWrite(INJ_PIN, HIGH);
}

void injLow()
{
    digitalWrite(INJ_PIN, LOW);
}

void setReady(bool on)
{
    digitalWrite(READY_PIN, on ? HIGH : LOW);
}

void heartbeat()
{
    Serial.print("mist shots=");
    Serial.print(shots);
    Serial.print(" busy=");
    Serial.println(pulsing ? 1 : 0);
}

void setup()
{
    pinMode(TRIG_PIN, INPUT_PULLUP);
    pinMode(INJ_PIN, OUTPUT);
    pinMode(READY_PIN, OUTPUT);
    injLow();
    setReady(true);
    Serial.begin(9600);
    stableTrig = digitalRead(TRIG_PIN);
    lastTrig = stableTrig;
    trigEdge = millis();
    lastHb = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(TRIG_PIN);

    if (raw != lastTrig)
    {
        trigEdge = now;
        lastTrig = raw;
    }

    if ((now - trigEdge) >= DEBOUNCE_MS && raw != stableTrig)
    {
        stableTrig = raw;
        if (stableTrig == LOW && !pulsing)
        {
            pulsing = true;
            pulseStart = now;
            shots++;
            injHigh();
            setReady(false);
        }
    }

    if (pulsing && (now - pulseStart) >= PULSE_MS)
    {
        pulsing = false;
        injLow();
        setReady(true);
    }

    if (now - lastHb >= HB_MS)
    {
        lastHb = now;
        heartbeat();
    }
}

// Harbor nav beacon: 500 ms on / 500 ms off on D12.
// Quiet mode switch on D3 (pull-up). Status over UART.

const int BEACON_PIN = 12;
const int QUIET_PIN = 3;
const unsigned long HALF_MS = 500;
const unsigned long STATUS_MS = 2000;

bool lampOn = false;
unsigned long lastToggle = 0;
unsigned long lastStatus = 0;
unsigned long risingCount = 0;
bool quietHeld = false;
bool wasQuiet = false;

void setBeacon(bool on)
{
    lampOn = on;
    digitalWrite(BEACON_PIN, on ? HIGH : LOW);
}

void emitTick()
{
    Serial.println("tick");
    risingCount++;
}

void publishStatus()
{
    Serial.print("nav rises=");
    Serial.print(risingCount);
    Serial.print(" quiet=");
    Serial.println(quietHeld ? 1 : 0);
}

bool readQuiet()
{
    return digitalRead(QUIET_PIN) == LOW;
}

void setup()
{
    pinMode(BEACON_PIN, OUTPUT);
    pinMode(QUIET_PIN, INPUT_PULLUP);
    setBeacon(false);
    Serial.begin(9600);
    lastToggle = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();
    quietHeld = readQuiet();

    if (quietHeld)
    {
        if (!wasQuiet)
        {
            setBeacon(false);
        }
        // Pause: do not advance lastToggle while held
    }
    else
    {
        if (wasQuiet)
        {
            // Resume: restart half-period from release
            lastToggle = now;
        }
        if (now - lastToggle >= HALF_MS)
        {
            lastToggle += HALF_MS;
            bool nextOn = !lampOn;
            setBeacon(nextOn);
            if (nextOn)
            {
                emitTick();
            }
        }
    }
    wasQuiet = quietHeld;

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus += STATUS_MS;
        publishStatus();
    }
}

// Control-panel key: toggles a status LED for the technician.
// Key on D2 (pull-up to Vcc, closes to ground), LED on D13.

const int KEY_PIN = 2;
const int LED_PIN = 13;
const unsigned long REPORT_MS = 1000;
const unsigned long SETTLE_MS = 40;

bool ledLit = false;
int stableLevel = HIGH;      // debounced key state
int lastRaw = HIGH;          // last raw sample
unsigned long lastChangeMs = 0;
unsigned long lastReport = 0;
unsigned long edgeCount = 0;

void writeLed(bool on)
{
    ledLit = on;
    digitalWrite(LED_PIN, on ? HIGH : LOW);
}

void flipLed()
{
    writeLed(!ledLit);
    edgeCount++;
}

void report()
{
    Serial.print("panel led=");
    Serial.print(ledLit ? 1 : 0);
    Serial.print(" edges=");
    Serial.println(edgeCount);
}

void setup()
{
    pinMode(KEY_PIN, INPUT_PULLUP);
    pinMode(LED_PIN, OUTPUT);
    writeLed(false);
    Serial.begin(9600);
    lastRaw = digitalRead(KEY_PIN);
    stableLevel = lastRaw;
    lastChangeMs = millis();
    lastReport = millis();
}

void loop()
{
    unsigned long t = millis();
    int raw = digitalRead(KEY_PIN);

    // Track raw changes; require the level to be stable for SETTLE_MS.
    if (raw != lastRaw)
    {
        lastRaw = raw;
        lastChangeMs = t;
    }

    if ((t - lastChangeMs) >= SETTLE_MS && raw != stableLevel)
    {
        int newLevel = raw;
        // Active-LOW key: press is HIGH-to-LOW after settle.
        if (stableLevel == HIGH && newLevel == LOW)
        {
            flipLed();
        }
        stableLevel = newLevel;
    }

    if (t - lastReport >= REPORT_MS)
    {
        lastReport = t;
        report();
    }
}

// Front porch gate chime.
// Gate contact on D3 (pull-up, active LOW when open), chime coil on D10.
// Keep a UART heartbeat alive for the monitoring hub.

const uint8_t GATE_PIN = 3;
const uint8_t CHIME_PIN = 10;
const unsigned long CHIME_MS = 1800;
const unsigned long HB_MS = 300;
const unsigned long DEBOUNCE_MS = 40;

unsigned long lastHb = 0;
unsigned long openCount = 0;

bool lastRawOpen = false;
bool stableOpen = false;
unsigned long rawChangeMs = 0;

bool chimeActive = false;
unsigned long chimeStartMs = 0;

void chimeHigh()
{
    digitalWrite(CHIME_PIN, HIGH);
}

void chimeLow()
{
    digitalWrite(CHIME_PIN, LOW);
}

void sendHb()
{
    Serial.println("gate-hb");
}

bool gateRawOpen()
{
    return digitalRead(GATE_PIN) == LOW;
}

void setup()
{
    pinMode(GATE_PIN, INPUT_PULLUP);
    pinMode(CHIME_PIN, OUTPUT);
    chimeLow();
    Serial.begin(9600);
    lastHb = millis();
    rawChangeMs = millis();
    lastRawOpen = gateRawOpen();
    stableOpen = lastRawOpen;
}

void loop()
{
    unsigned long now = millis();

    // Debounce gate contact: require a stable state for DEBOUNCE_MS.
    bool rawOpen = gateRawOpen();
    if (rawOpen != lastRawOpen)
    {
        lastRawOpen = rawOpen;
        rawChangeMs = now;
    }
    else if ((now - rawChangeMs) >= DEBOUNCE_MS && stableOpen != rawOpen)
    {
        stableOpen = rawOpen;
        if (stableOpen && !chimeActive)
        {
            // Settled open event: start non-blocking chime pulse.
            openCount++;
            chimeActive = true;
            chimeStartMs = now;
            chimeHigh();
        }
    }

    // End chime pulse when its full length has elapsed.
    if (chimeActive && (now - chimeStartMs) >= CHIME_MS)
    {
        chimeActive = false;
        chimeLow();
    }

    // Heartbeat runs independently of the chime.
    if ((now - lastHb) >= HB_MS)
    {
        lastHb = now;
        sendHb();
    }
}

// Process-skid flow monitor with low-flow alarm lamp.
// Flow transducer on A0 (2 mV per L/h), alarm lamp on D8.

const int FLOW_PIN = A0;
const int ALARM_PIN = 8;
const float LOW_FLOW_LPH = 100.0f;
const float HYST_LPH = 10.0f;
const unsigned long LOG_MS = 500;

bool alarmLit = false;
unsigned long lastLog = 0;

float readFlowLph()
{
    int counts = analogRead(FLOW_PIN);
    float mv = (float)counts * 5000.0f / 1023.0f;
    return mv / 2.0f;
}

void setAlarm(bool on)
{
    alarmLit = on;
    digitalWrite(ALARM_PIN, on ? HIGH : LOW);
}

void setup()
{
    pinMode(ALARM_PIN, OUTPUT);
    digitalWrite(ALARM_PIN, LOW);
    Serial.begin(9600);
    lastLog = millis();
}

void loop()
{
    float flowLph = readFlowLph();

    if (!alarmLit && flowLph < LOW_FLOW_LPH)
    {
        setAlarm(true);
    }
    else if (alarmLit && flowLph > (LOW_FLOW_LPH + HYST_LPH))
    {
        setAlarm(false);
    }

    unsigned long now = millis();
    if (now - lastLog >= LOG_MS)
    {
        lastLog = now;
        Serial.print("flow: ");
        Serial.println(flowLph, 1);
    }
}

// Linear rail carriage motor enable with end-stop.
// Limit switch on D2 (pull-up to GND when hit), motor enable on D13.
// Jog button on D4 (pull-up) requests motion when clear.

const int LIMIT_PIN = 2;
const int MOTOR_PIN = 13;
const int JOG_PIN = 4;
const unsigned long DEBOUNCE_MS = 25;
const unsigned long STATUS_MS = 900;

int stableLimit = HIGH;
int lastLimit = HIGH;
unsigned long limitEdge = 0;
bool motorEnabled = false;
unsigned long lastStatus = 0;
unsigned long hitCount = 0;

bool limitActiveRaw()
{
    return digitalRead(LIMIT_PIN) == LOW;
}

void setMotor(bool enabled)
{
    motorEnabled = enabled;
    digitalWrite(MOTOR_PIN, enabled ? HIGH : LOW);
}

void publishStatus()
{
    Serial.print("rail motor=");
    Serial.print(motorEnabled ? 1 : 0);
    Serial.print(" hits=");
    Serial.println(hitCount);
}

void setup()
{
    pinMode(LIMIT_PIN, INPUT_PULLUP);
    pinMode(JOG_PIN, INPUT_PULLUP);
    pinMode(MOTOR_PIN, OUTPUT);
    setMotor(false);
    Serial.begin(9600);
    stableLimit = digitalRead(LIMIT_PIN);
    lastLimit = stableLimit;
    limitEdge = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();
    int raw = digitalRead(LIMIT_PIN);

    if (raw != lastLimit)
    {
        limitEdge = now;
        lastLimit = raw;
    }

    if ((now - limitEdge) >= DEBOUNCE_MS && raw != stableLimit)
    {
        stableLimit = raw;
        if (stableLimit == LOW)
        {
            hitCount++;
        }
    }

    bool hit = (stableLimit == LOW);
    bool jog = (digitalRead(JOG_PIN) == LOW);

    if (hit)
    {
        setMotor(false);
    }
    else if (jog)
    {
        setMotor(true);
    }
    else
    {
        setMotor(false);
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        publishStatus();
    }
}

// Shop bench run/stop: mushroom estop toggles the "machine armed" lamp.
// Estop contact on D6 (NC to ground via switch, pull-up), armed lamp on D9.

const uint8_t ESTOP_PIN = 6;
const uint8_t ARMED_PIN = 9;
const unsigned long BEAT_MS = 1200;
const unsigned long SETTLE_MS = 50;

bool armed = false;
uint8_t stableSample = HIGH;
uint8_t lastRaw = HIGH;
unsigned long lastChangeMs = 0;
unsigned long lastBeat = 0;
unsigned long pressCount = 0;

void writeArmed(bool level)
{
