    Serial.println(v, 0);
}

void setup()
{
    pinMode(WARN_PIN, OUTPUT);
    pinMode(MUTE_PIN, INPUT_PULLUP);
    digitalWrite(WARN_PIN, LOW);
    Serial.begin(9600);
    lastPrint = millis();
    lastSample = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        rpm = readRpm();
        trackExtremes(rpm);
        updateWarn(rpm);
    }

    if (now - lastPrint >= PERIOD_MS)
    {
        lastPrint = now;
        printRpm(rpm);
        Serial.print("spindle min=");
        Serial.print(rpmMin, 0);
        Serial.print(" max=");
        Serial.println(rpmMax, 0);
        rpmMin = 99999.0f;
        rpmMax = 0.0f;
    }
}

// Recording-studio panic siren with non-blocking pulse and heartbeat.
// Panic button on D4 (pull-up), siren driver on D7.

const int PANIC_PIN = 4;
const int SIREN_PIN = 7;
const unsigned long PULSE_MS = 2500;
const unsigned long HB_MS = 400;
const unsigned long DEBOUNCE_MS = 35;

bool sirenOn = false;
unsigned long sirenStart = 0;
unsigned long lastHb = 0;

int stableBtn = HIGH;
int lastBtn = HIGH;
unsigned long btnChanged = 0;

void sirenHigh()
{
    digitalWrite(SIREN_PIN, HIGH);
}

void sirenLow()
{
    digitalWrite(SIREN_PIN, LOW);
}

void sendHb()
{
    Serial.println("hb");
}

void setup()
{
    pinMode(PANIC_PIN, INPUT_PULLUP);
    pinMode(SIREN_PIN, OUTPUT);
    sirenLow();
    Serial.begin(9600);
    stableBtn = digitalRead(PANIC_PIN);
    lastBtn = stableBtn;
    btnChanged = millis();
    lastHb = millis();
}

void loop()
{
    unsigned long now = millis();
    int btn = digitalRead(PANIC_PIN);

    // Only restart the settle timer when the raw reading actually changes.
    if (btn != lastBtn)
    {
        lastBtn = btn;
        btnChanged = now;
    }

    if ((now - btnChanged) >= DEBOUNCE_MS && btn != stableBtn)
    {
        stableBtn = btn;
        if (stableBtn == LOW && !sirenOn)
        {
            sirenOn = true;
            sirenStart = now;
            sirenHigh();
        }
    }

    if (sirenOn && (now - sirenStart) >= PULSE_MS)
    {
        sirenOn = false;
        sirenLow();
    }

    if (now - lastHb >= HB_MS)
    {
        lastHb = now;
        sendHb();
    }
}

// Safe-deposit vault lock latch.
// Request button on D2, door-closed sense on D3 (both pull-up), lock solenoid on D9.

const int REQ_PIN = 2;
const int DOOR_PIN = 3;
const int LOCK_PIN = 9;
const unsigned long DEBOUNCE_MS = 35;
const unsigned long STATUS_MS = 1000;

bool locked = false;
int stableReq = HIGH;
int lastReq = HIGH;
unsigned long reqEdge = 0;
unsigned long lastStatus = 0;
unsigned long engageCount = 0;

void setLock(bool on)
{
    locked = on;
    digitalWrite(LOCK_PIN, on ? HIGH : LOW);
}

void publishStatus()
{
    Serial.print("vault lock=");
    Serial.print(locked ? 1 : 0);
    Serial.print(" engages=");
    Serial.println(engageCount);
}

bool doorClosed()
{
    return digitalRead(DOOR_PIN) == LOW;
}

void setup()
{
    pinMode(REQ_PIN, INPUT_PULLUP);
    pinMode(DOOR_PIN, INPUT_PULLUP);
    pinMode(LOCK_PIN, OUTPUT);
    setLock(false);
    Serial.begin(9600);
    stableReq = digitalRead(REQ_PIN);
    lastReq = stableReq;
    reqEdge = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    // Unlock immediately when the door opens.
    if (locked && !doorClosed())
    {
        setLock(false);
    }

    int raw = digitalRead(REQ_PIN);

    if (raw != lastReq)
    {
        reqEdge = now;
        lastReq = raw;
    }

    if ((now - reqEdge) >= DEBOUNCE_MS && raw != stableReq)
    {
        stableReq = raw;
        if (stableReq == LOW && doorClosed() && !locked)
        {
            setLock(true);
            engageCount++;
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        publishStatus();
    }
}

// Walk-in cooler compressor controller.
// Cabinet probe on A3 (10 mV/°C), compressor on D7, service switch on D4.

const int TEMP_PIN = A3;
const int COMP_PIN = 7;
const int SERVICE_PIN = 4;
const float COOL_ON_C = 8.0f;
const float COOL_OFF_C = 4.0f;
const float MV_PER_C = 10.0f;
const float MIN_VALID_C = 0.0f;
const float MAX_VALID_C = 60.0f;
const unsigned long TICK_MS = 50;
const unsigned long STATUS_MS = 1000;
const int HOLD_N = 3;

bool cooling = false;
int onHold = 0;
int offHold = 0;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
float tempC = 0.0f;
bool sensorFault = false;

float readTempC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1024.0f);
    return mv / MV_PER_C;
}

bool sensorValid(float t)
{
    // Reject floating/disconnected probe and out-of-range readings.
    if (t < MIN_VALID_C || t > MAX_VALID_C)
    {
        return false;
    }
    return true;
}

void setCompressor(bool on)
{
    cooling = on;
    digitalWrite(COMP_PIN, on ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("cooler: ");
    Serial.print(tempC, 1);
    Serial.print(" C comp=");
    Serial.println(cooling ? "ON" : "OFF");
}

void setup()
{
    pinMode(COMP_PIN, OUTPUT);
    pinMode(SERVICE_PIN, INPUT_PULLUP);
    setCompressor(false);
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        tempC = readTempC();
        bool service = (digitalRead(SERVICE_PIN) == LOW);
        sensorFault = !sensorValid(tempC);

        if (service || sensorFault)
        {
            onHold = 0;
            offHold = 0;
            setCompressor(false);
        }
        else
        {
            if (tempC >= COOL_ON_C)
            {
                onHold++;
            }
            else
            {
                onHold = 0;
            }

            if (tempC <= COOL_OFF_C)
            {
                offHold++;
            }
            else
            {
                offHold = 0;
            }

            if (onHold >= HOLD_N)
            {
                setCompressor(true);
            }
            else if (offHold >= HOLD_N)
            {
                setCompressor(false);
            }
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Patio weather node: TMP36 logger with hold-to-freeze button.
// TMP36 on A0 (10 mV/°C + 500 mV), freeze button on D5, range lamp on D7.

const int TEMP_PIN = A0;
const int FREEZE_PIN = 5;
const int RANGE_PIN = 7;
const float MV_PER_C = 10.0f;
const float OFFSET_MV = 500.0f;
const float LOW_C = -10.0f;
const float HIGH_C = 50.0f;
const unsigned long PERIOD_MS = 1000;

unsigned long lastPrint = 0;
float tempC = 0.0f;
float frozenC = 0.0f;
bool freezeHeld = false;
bool wasHeld = false;
unsigned long samples = 0;

float readTempC()
{
    int raw = analogRead(TEMP_PIN);
    float volts = raw * (5.0f / 1024.0f);
    return (volts - (OFFSET_MV / 1000.0f)) * 100.0f;
}

void updateRangeLamp(float c)
{
    bool ok = (c >= LOW_C) && (c <= HIGH_C);
    digitalWrite(RANGE_PIN, ok ? LOW : HIGH);
}

void printTemp(float c)
{
    Serial.print("Temp: ");
    Serial.println(c, 1);
}

void setup()
{
    pinMode(FREEZE_PIN, INPUT_PULLUP);
    pinMode(RANGE_PIN, OUTPUT);
    digitalWrite(RANGE_PIN, LOW);
    Serial.begin(9600);
    lastPrint = millis();
}

void loop()
{
    tempC = readTempC();
    freezeHeld = (digitalRead(FREEZE_PIN) == LOW);

    // Capture the last sample at the moment the button is pressed.
    if (freezeHeld && !wasHeld)
    {
        frozenC = tempC;
    }
    wasHeld = freezeHeld;

    float report = freezeHeld ? frozenC : tempC;
    updateRangeLamp(report);

    unsigned long now = millis();
    if (now - lastPrint >= PERIOD_MS)
    {
        lastPrint = now;
        samples++;
        printTemp(report);
        Serial.print("weather n=");
        Serial.println(samples);
    }
}

